import assert from 'node:assert/strict';
import { parseImportText, parseCatalogJSON } from './import.js';

const source = [{ code: 'SC1003', title: 'Computational Thinking', au: 3, indexes: [{ id: '10011', sessions: [{ day: 0, start: 540, end: 600, type: 'LEC', venue: 'LT2', weeks: [1, 3, 5] }] }] }];
const catalog = parseCatalogJSON(JSON.stringify(source));
assert.equal(catalog[0].indexes[0].sessions[0].start, 540);
assert.deepEqual(catalog[0].indexes[0].sessions[0].weeks, [1, 3, 5]);
const imported = parseImportText('SC1003 10011 MON 09:00-10:00 LEC LT2\nTUE 1330-1430 TUT TR1', catalog);
assert.deepEqual(imported.matches, [{ code: 'SC1003', indexId: '10011' }]);
assert.deepEqual(imported.sessions[0], { code: 'SC1003', day: 0, start: 540, end: 600, type: 'LEC', venue: 'LT2' });
assert.equal(imported.sessions[1].day, 1);
assert.equal(imported.sessions[1].start, 810);
const weekend=parseImportText('SC1001 10001 SAT 09:30-10:20 LEC/STUDIO LT19A',[]).sessions[0];
assert.equal(weekend.day,5);assert.equal(weekend.type,'LEC/STUDIO');assert.equal(weekend.venue,'LT19A');
assert.deepEqual(parseImportText('SC1003\n10011', catalog).matches, [{ code: 'SC1003', indexId: '10011' }]);
assert.deepEqual(parseImportText('10011', catalog).matches, [{ code: 'SC1003', indexId: '10011' }]);
assert.ok(imported.warnings.length);
assert.equal(parseImportText('SC1003 99999', catalog).matches[0].indexId, null);
assert.equal(parseImportText('SC1003 MON 25:00-26:00', catalog).sessions.length, 0);
assert.equal(parseImportText('SC1003 MON 10:00-09:00', catalog).sessions.length, 0);
assert.ok(parseImportText('a vague image', catalog).warnings.length);
assert.throws(() => parseCatalogJSON('{'), /valid JSON/);
assert.throws(() => parseCatalogJSON('[]'), /nonempty/);
assert.throws(() => parseCatalogJSON(JSON.stringify([...source, ...source])), /duplicate/);
const invalid = structuredClone(source);
invalid[0].indexes[0].sessions[0].end = 400;
assert.throws(() => parseCatalogJSON(JSON.stringify(invalid)), /start\/end/);
const strings = structuredClone(source);
Object.assign(strings[0].indexes[0].sessions[0], { day: 'MONDAY', start: '09:00', end: '10:00' });
assert.equal(parseCatalogJSON(JSON.stringify(strings))[0].indexes[0].sessions[0].start, 540);
const savedDemo = structuredClone(source);
savedDemo[0].indexes[0].id = 'DEMO-10001';
assert.equal(parseCatalogJSON(JSON.stringify(savedDemo))[0].indexes[0].id, 'DEMO-10001');
assert.deepEqual(parseImportText('SC1003 DEMO-10001', savedDemo).matches, [{ code: 'SC1003', indexId: 'DEMO-10001' }]);
assert.equal(parseImportText('SC1003 DEMO-10011', catalog).matches[0].indexId, null);
const savedImport = structuredClone(source);
savedImport[0].au = 0;
savedImport[0].indexes[0].id = 'IMPORTED-ab12ef';
assert.equal(parseCatalogJSON(JSON.stringify(savedImport))[0].au, 0);
assert.equal(parseImportText('SC1003 IMPORTED-ab12ef', savedImport).matches[0].indexId, 'IMPORTED-ab12ef');
savedImport[0].indexes[0].sessions[0].weeks = [14];
assert.throws(() => parseCatalogJSON(JSON.stringify(savedImport)), /1 to 13/);
console.log('Import parser tests passed.');
